      threshold,
      minFlightsPerRoute,
    };

    const [
      filterOptions,
      heroStats,
      delayDistribution,
      dayOfWeek,
      departureHour,
      busiestDays,
      worstDays,
      worstRoutes,
      flightNumbers,
      aircraftUsage,
      topDelays,
      dailyOtp,
      monthlyBreakdown,
      windDelays,
      visibilityDelays,
      precipDelays,
      weatherCodeDelays,
      crosswindDelays,
      worstWeatherDays,
      delayImpact,
      worstDelayDays,
    ] = await Promise.all([
      getFilterOptions(),
      getHeroStats(filterConfig),
      getDelayDistribution(filterConfig),
      getDayOfWeekDistribution(filterConfig),
      getHourDistribution(filterConfig),
