      weatherCodeDelays,
      crosswindDelays,
      worstWeatherDays,
      delayImpact,
      worstDelayDays,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/stats]', err);
    return debugError('Query failed', 500);
  }
};

